"""Customer features: one-hot encoding of plan and region."""
from sklearn.preprocessing import OneHotEncoder

COLUMNS = ["plan", "region"]


def fit_encoder(rows):
    encoder = OneHotEncoder(sparse=False, handle_unknown="ignore")
    return encoder.fit(rows)


def encode(encoder, rows):
    return encoder.transform(rows)


def feature_names(encoder):
    return list(encoder.get_feature_names(COLUMNS))

