"""Churn and spend models with scikit-learn, plus the metrics the report prints."""
from sklearn.ensemble import BaggingClassifier, RandomForestClassifier
from sklearn.linear_model import LinearRegression
from sklearn.metrics import SCORERS, mean_squared_error
from sklearn.tree import DecisionTreeClassifier


def churn_bagging(X, y, seed=0):
    model = BaggingClassifier(base_estimator=DecisionTreeClassifier(max_depth=3),
                              n_estimators=5, random_state=seed)
    return model.fit(X, y)


def churn_forest(X, y, seed=0):
    model = RandomForestClassifier(n_estimators=5, max_features="auto", random_state=seed)
    return model.fit(X, y)


def spend_model(X, y):
    return LinearRegression(normalize=True).fit(X, y)


def rmse(y_true, y_pred):
    return float(mean_squared_error(y_true, y_pred, squared=False))


def known_metric(name):
    return name in SCORERS

